  ('quaagl', 'Quaagl', 'der', '', '', 'Grundwortschatz Wienerisch', 'Quargl', '[{"kategorie": "wörtlich", "text": "\"Quargel\" (vom mittelhochdeutschen \"quarc\"=\"Quarkkäse\")"}, {"kategorie": "allg.", "text": "\"Quargel\" (Frischkäse aus pasteurisierter Kuhmilch mit weicher, cremiger Konsistenz und mildem Geschmack. Er ist eiweißreich, feucht, wird als Würfel oder Aufstrich angeboten und häufig in der österreichischen Küche verwendet, auch gewürzt oder mit Kräutern verfeinert), \"stark riechender Sauermilchkäse\", \"Käse mit ausgeprägter Reifungsnote\" (Deutschland): \"Harzer Käse\""}, {"kategorie": "fig.", "text": "Unsinn, Quatsch, Stuss, [[Schmafuu]] ([[Red ned so an Quaagl!]])"}]'::jsonb, 'Da Quaagl schdinkd wia da Teifä, schmeckd owa gettlich!'),
  ('quaagln', 'quaagln', '', '', '', 'Grundwortschatz Wienerisch', 'quargeln', '[{"kategorie": "wörtlich", "text": "\"quargeln\" (Verbalableitung von [[Quargel]]=\"Käse\", vom mittelhochdeutschen \"quarc\"=\"Quarkkäse\")"}, {"kategorie": "fig.", "text": "\"Käse reden\", schwafeln, dumm daherreden, quatschen, [[schwurbeln]], [[gatschen]]"}, {"kategorie": "auch", "text": "\"schwer verständlich sprechen\", \"undeutlich sprechen\", \"nuscheln\""}]'::jsonb, 'Dea quaagld seit zeen Minuutn und soogd trotzdem nix!'),
