  ('querulant', 'Querulant', 'der', '', '', 'Grundwortschatz Wienerisch', 'Querulant', '[{"kategorie": "wörtlich", "text": "\"Querulant\" (vom lateinischen \"querulans\"=\"sich beklagend\")"}, {"kategorie": "allg.", "text": "Quertreiber (jemand, der versucht, etwas mit unehrlichen oder unfairen Mitteln zu vereiteln), Intrigant, Unruhestifter, [[Hacklschmeissa]], [[Oaschklääzn]], [[Queabrooda]]"}]'::jsonb, 'Noo kaa Schdich draussn, und dea Querulant faungd schoo zum Dischkutian au!'),
  ('quetschn', 'Quetschn', 'die', '', '', 'Echte Wiener Schmähperlen', 'Quetschen', '[{"kategorie": "wörtlich", "text": "\"Quetschen\" (vom mittelhochdeutschen \"quetzen\"=\"quetschen\")"}, {"kategorie": "Musik, scherzhaft für", "text": "\"Quetschinstrument\" (dessen Blasebalg ständig ausgezogen und dann wieder \"zugequetscht\" werden muss);  Akkordeon, [[Ziehharmonika]], [[Maurerklampfen]], [[Maurerklavier]], [[Quietschkistn]], [[Wanzenpresse]], [[Flohpresse]]"}, {"kategorie": "allg.", "text": "\"Miniladen\", \"gewerblicher oder handwerklicher Kleinstbetrieb\" (aus welchem trotz der beengten Räumlichkeiten das Maximum \"herausgequetscht\" wird), \"Ein-Mann-Betrieb\", \"Kramerladen\""}, {"kategorie": "Gastronomie", "text": "\"Kleinnstgaststätte, \"Schankstube\" (in das man sich \"hineinquetschen\" muss, um einen Platz zu finden), \"Kaschemme\", \"Stehbeisl\", [[Hnterhofbeisl]], [[Tschocherl]]"}]'::jsonb, 'In dera Quetschn kaunnst ned umfoin - dafia is aafoch ka Plotz!'),
  ('quetschnziaga', 'Quetschnziaga', 'der', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Quetschenzieher', '[{"kategorie": "wörtlich", "text": "\"Quetschenzieher\" (Determinativkompositum aus [[Quetschen]]=\"Ziehharmonika\" und \"Zieher\"=\"Musiker, der am Blasebalg der [[Quetschen]] [Ziehharmonika] zieht)\""}, {"kategorie": "Musik, scherzhaft für", "text": "Harmonikaspieler, Akkordeonist, \"Balgwürger\", [[Quetschnschbüüla]]"}]'::jsonb, 'Quetschnziaga, schbüü auf - gib eam, Schdimmung!'),
  ('quetschnschbueuela', 'Quetschnschbüüla', 'der', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Quetschenspieler', '[{"kategorie": "wörtlich", "text": "\"Quetschenspieler\" (Determinativkompositum aus [[Quetschen]]=\"Ziehharmonika\" und \"Spieler\"=\"Musikant\")"}, {"kategorie": "Musik, scherzhaft für", "text": "Harmonikaspieler, Akkordeonist, \"Balgwürger\", [[Quetschnziaga]]"}]'::jsonb, 'Bei da Poika hoit da Quetschnschbüüla in Ritmus zsaumm - ea fiad, und da Rest foigd eam!'),
  ('quatschn', 'quatschn', '', '', '', 'Grundwortschatz Wienerisch', 'quatschen', '[{"kategorie": "wörtlich", "text": "\"quatschen\" (lautmalerisches Wort, welches das Geräusch von schnell oder unbedacht gesprochenen Worten imitiert)"}, {"kategorie": "allg.", "text": "\"sich ungezwungen unterhalten\", miteinander plaudern, [[plauschen]], [[tratschen]], (auch:) \"etwas ausreden\", \"besprechen\""}, {"kategorie": "fig.", "text": "Unsinn reden, quasseln, schwatzen, (Deutschland): \"labern\""}]'::jsonb, 'Quatsch ma moi olle mitanaunda!'),
  ('quatsch', 'Quatsch', 'der', '', '', 'Grundwortschatz Wienerisch', 'Quatsch', '[{"kategorie": "wörtlich", "text": "\"Quatsch\" (lautmalerisches Wort, das ein schmatzendes, matschiges Geräusch nachahmt)"}, {"kategorie": "allg.", "text": "\"breiige Masse\" (\"etwas Zedrücktes, Weiches, Formloses\"), Matsch, Schlamm, Pampe, [[Gatsch]]"}, {"kategorie": "fig.", "text": "\"Unsinn\", \"Nonsens\", \"dummes Zeug\", \"leeres Geschwätz\",  Käse, Stuss, [[Topfn]], [[Lavendel]], [[Schmonzes]], [[Schmarren]], [[Quargel]], [[Schaas mit Quastl]]"}]'::jsonb, 'Wos do in da Kistn liigd, is ka Obst mea - des is a brauna Quatsch volla Maadn!'),
  ('tuatnglockn', 'Tuatnglockn', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'Tortenglocke', '[{"kategorie": "wörtlich", "text": "\"Tortenglocke\" (Determinativkompositum aus \"Torte\"=\"Kuchen\" und \"Glocke\"=\"Haube\")"}, {"kategorie": "allg.", "text": "\"Tortenhaube\", \"Tortensturz\", \"Servierhaube für Torten\", \"Präsentierhaube für Torten\""}]'::jsonb, ''),
  ('lack', 'Lack', 'der', '', '', 'Grundwortschatz Wienerisch', 'Lack', '[{"kategorie": "wörtlich", "text": "\"Lack\" (vom lateinischen \"lacca\"=\"Firnis\" [klarer, transparenter Überzug, der vor allem in der Malerei, Restaurierung und Holzverarbeitung verwendet wird. Er dient dazu, Oberflächen zu schützen, Farben zu vertiefen und einen einheitlichen Glanz zu erzeugen])"}, {"kategorie": "techn.", "text": "Schutzüberzug, Beschichtung, Schutzschicht"}, {"kategorie": "scherzhaft für", "text": "\"abgestandenes Bier\", \"Bier ohne Kohlensäure\", \"Schaumleiche\", [[Fenstaschwitz]], [[Gloodan]], [[Affenbrunzlert]]"}]'::jsonb, 'Kack mit Lack!'),
  ('sozialporno', 'Sozialporno', 'der', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Sozialporno', '[{"kategorie": "wörtlich", "text": "\"Sozialporno\" (Determinativkompositum aus \"sozial\"=\"gesellschaftlich\" und \"Porno\"=\"Entblößung\")"}, {"kategorie": "scherzhaft für", "text": "\"primitive Dokusoap\" (bei der die Teilnehmer ihre Seele entblößen), \"Seelenstriptease-Show\", \"voyeuristische Dokusoap\", \"Elend zum Anglotzen\""}]'::jsonb, 'De Sendung mochd aus Ööländ a Schbektakl und vakummd damit zu an reinan Sozialporno!'),
  ('radiira', 'Radiira', 'der', '', '', 'Grundwortschatz Wienerisch', 'Radierer', '[{"kategorie": "wörtlich", "text": "\"Radierer\" (vom lateinischen \"radere\"=\"glattschaben\")"}, {"kategorie": "allg.", "text": "\"Radiergummi\", [[Radetzky]], [[Putzweg]]"}]'::jsonb, ''),
  ('radetzky', 'Radetzky', 'der', '', '', 'Echte Wiener Schmähperlen', 'Radetzky', '[{"kategorie": "wörtlich, Schülerjargon", "text": "\"Radiergummi\" (wobei \"Radetzky\" die verballhornte Form von \"Radierer\" ist - abgeleitet vom lateinischen \"radere\"=\"glattschaben\")"}, {"kategorie": "allg.", "text": "\"Radetzky\" („Radetzky“ als Bezeichnung für den Radierer entstand aus der Popularität des österreichischen Feldmarschalls Josef Wenzel Graf Radetzky [1766-1858], sowie der Lautähnlichkeit dessen Familiennamens zu „radieren“ und der ironischen Übertragung militärischer „Beseitigung“ auf Schreibfehler), \"Radiergummi\", [[Radierer]], [[Putzweg]]"}]'::jsonb, 'Radetzky schau owe!'),
  ('radetzkymarsch', 'Radetzkymarsch', 'der', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Radetzkymarsch', '[{"kategorie": "wörtlich", "text": "\"Radetzkymarsch\" (Determinativkompositum aus \"Radetzky\"=\"österreichischer Feldmarschall Josef Wenzel Graf Radetzky\" und \"Marsch\"=\"Militärmarsch\")"}, {"kategorie": "Musik", "text": "\"Musikstück von [[Johann]] Strauß Vater\" (Militärmarsch, Armeemarsch)"}, {"kategorie": "", "text": "Er ist dem österreichischen Feldmarschall Josef Wenzel Graf Radetzky [1766-1858] gewidmet, wurde 1848 im [[Wasserglacis]] uraufgeführt und ist bis heute die Schlussnummer beim weltberühmten [[Neujahrskonzerts]] der [[Wiener]] Philharmoniker)"}]'::jsonb, 'wem in Radetzkymarsch bloosn'),
  ('raadla', 'Raadla', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Radler', '[{"kategorie": "wörtlich", "text": "\"Radler\" (kurz für \"Radfahrer\" - abgeleitet von \"radeln\": Das Verb entstand in der zweiten Hälfte des 19. Jahrhunderts, als sich das Fahrrad im Alltag durchsetzte, und löste das sperrige ältere Wort velozipedieren ab. Es handelt sich um eine Neubildung zum Substantiv Fahrrad. Sprachlich knüpft der Ausdruck vermutlich an das bairische radeln [„sich im Kreis drehen“] an und zugleich an das in der Wiener Umgangssprache verbreitete herumradeln, das ironisch für zielloses oder vergebliches Umherfahren stand)"}, {"kategorie": "allg.", "text": "Fahrradfahrer, Pedalritter, Radfahrer, Biker"}, {"kategorie": "Gastronomie", "text": "\"Biermischgetränk\", \"Erfrischungsgetränk aus Bier und Limonade\" (der Begriff \"Radler\" stammt aus dem Deutschen und bedeutet wörtlich \"Radfahrer\". Das Getränk soll in den 1920er Jahren in Bayern entstanden sein, als Gastwirte ein erfrischendes und leichtes Getränk für Radfahrer suchten, die oft durstig in ihren Biergärten einkehrten)"}, {"kategorie": "hist.", "text": "Eine beliebte Legende besagt, dass der bayerische Wirt Franz Xaver Kugler das Getränk erfunden hat, als er eine größere Gruppe Radfahrer bewirten musste und sein Bierbestand knapp wurde. Um sicherzustellen, dass das Bier für alle reichte, mischte er es mit Zitronenlimonade, und so entstand der Radler."}]'::jsonb, 'Mit Hööm, Brüün und Karbonrauman füül I mi ois Raadla wiara Profi!'),
  ('roobnoasch', 'Roobnoasch', 'der', '', '', 'Grundwortschatz Wienerisch', 'Rabenarsch', '[{"kategorie": "wörtlich", "text": "\"Rabenarsch\" (Determinativkompositum aus \"Rabe\"=\"Rabenvogel\" und \"Arsch\"=\"Hintern\")"}, {"kategorie": "scherzhaft für", "text": "\"Rabenhintern\", \"Rabenpopo\", \"rabenschwarzer Arsch\""}]'::jsonb, ''),
  ('raandl', 'Raandl', '', '', '', 'Grundwortschatz Wienerisch', 'Randl', '[{"kategorie": "wörtlich", "text": "\"Rändchen\" (Verkleinerungs form von \"Rand\"=\"der Vorgang/Moment des In-Gang-Setzens\", vom mittelhochdeutschen \"rennen\"=\"laufen machen\", Kausativum zu \"rinnen\" [nicht verwandt mit dem Substantiv \"Rand\"=\"Einfassung\"!!!!])"}, {"kategorie": "allg.", "text": "\"ganz kurze Zeitspanne\", \"Augenblickchen\", \"Momentchen\""}]'::jsonb, 'Schau nua auf a Raandl eine!'),
