  ('raund', 'Raund', 'der', '', '', 'Grundwortschatz Wienerisch', 'Rand', '[{"kategorie": "wörtlich", "text": "\"Rand\" (vom mittelhochdeutschen \"rennen\"=\"laufen machen\", Kausativum zu \"rinnen\" [nicht verwandt mit dem Substantiv \"Rand\"=\"Einfassung\"!!!]) 2. (allg.) \"der Vorgang/Moment des In-Gang-Setzens\", Schwung, Impuls, Anlauf"}, {"kategorie": "temporal", "text": "\"ganz kurze Zeitspanne\", \"Augenblickchen\", \"Momentchen\""}, {"kategorie": "fig.", "text": "\"heiterer Verlauf\", Spaß, Jux, Schabernack, [[Hetz]], [[Gaudi]]"}, {"kategorie": "dialektal für", "text": "Mund, Schnauze, Klappe, [[Goschn]], [[Pappn]]"}]'::jsonb, 'Kumm nua auf an Raund vuabei - muassd jo ned laung bleibm!'),
  ('raundae', 'Raundä', 'das', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Rendez', '[{"kategorie": "dialektale Kurzform für:", "text": "\"Rendezvous\" (vom französischen \"rendez-vous\"=\"Stelldichein\" bzw. \"Zusammentreffen\")"}, {"kategorie": "allg.", "text": "Verabredung, (engl.) \"Date\", (frz.) \"Tête-[[-T]]ête\""}]'::jsonb, 'Dea muass heit a Raundä haum - so wiara si de Gatschwöön aufgföönd hod!'),
