  ('rappae', 'Rappä', 'der', '', '', 'Grundwortschatz Wienerisch', 'Rappel', '[{"kategorie": "wörtlich", "text": "\"Rappel\" (vom mittelhochdeutschen \"rappen\"=\"klappernde/schlagende Geräusche verursachen\")"}, {"kategorie": "fig.", "text": "\"plötzlicher Anfall von Wahnsinn oder Zorn\", \"verrückte Anwandlung\" Ausbruch, Ausraster"}]'::jsonb, ''),
  ('rappaekopf', 'Rappäkopf', 'der', '', '', 'Grundwortschatz Wienerisch', 'Rappelkopf', '[{"kategorie": "wörtlich", "text": "\"Rappelkopf\" (Determinativkompositum aus \"Rappel\"=\"Wirrsal\" und \"Kopf\"=[[Schädel]])"}, {"kategorie": "allg.", "text": "Wirrkopf, Knallkopf, Verrückter, Spinner, \"schräger Vogel\", [[Schdruudlkopf]]"}, {"kategorie": "", "text": "\"jähzorniger Mensch\", Heißsporn, Hitzkopf, \"störrischer Esel\""}]'::jsonb, 'I hob dem Rappäkopf gsoogd, ea soi de Goschn hoitn - owa dea head nua si sööwa!'),
  ('rappaekopfad', 'rappäkopfad', '', '', '', 'Grundwortschatz Wienerisch', 'rappelkopfert', '[{"kategorie": "wörtlich", "text": "\"rappelköpfig\" (Determinativkompositum aus [[Rappel]]=\"Wirrsal\" und \"köpfig\"=[[schädlert]])"}, {"kategorie": "allg.", "text": "\"rappelköpfig\", \"knallköpfig\", \"wirr im Kopf\", verrückt, \"schief gewickelt\", [[spinnert]]"}, {"kategorie": "", "text": "hitzköpfig, jähzornig, \"leicht erregbar\", \"auf Krawall gebürstet\""}]'::jsonb, 'A bissl rappäkopfad muassd schoo sei, waunnsd so an Saundhoosn heiratsd!'),
