  ('raatschn', 'Raatschn', 'die', '', '', 'Grundwortschatz Wienerisch', 'Ratschen', '[{"kategorie": "wörtlich", "text": "\"Ratsche\" (vom mittelhochdeutschen \"ratschen\"=\"schnarren\")"}, {"kategorie": "allg.", "text": "\"Schnarre\" (selbstklingendes Holzinstrument, das durch Drehen oder Schütteln ein lautes klapperndes Geräusch erzeugt), Osterratsche, Karfreitagsratsche"}, {"kategorie": "fig., in Bezug auf Personen", "text": "Tratsche, Tratschweib, Tratschziege, Klatschtante, Klatschmaul, [[Schnoodan]], [[Tritschn]], [[Ratschkaatl]]"}, {"kategorie": "Gaunersprache", "text": "Maschinenpistole, [[Nähmaschine]], [[Ratata]], [[Barassera]], [[Pampam]], [[Mandoline]], [[Spradern]], [[Spritzn]]"}]'::jsonb, 'In da Karwochn schweing de Glockn, und de Raatschn iwanimmd eanan Dienst!'),
  ('raatschkaatl', 'Raatschkaatl', 'die', '', '', 'Echte Wiener Schmähperlen', 'Ratschkathl', '[{"kategorie": "wörtlich", "text": "\"die Tratsch-Katharina\" (Determinativkompositum aus [[Ratsch]]=\"Tratsch\" und [[Kathl]]=Kosename für \"Katharina\")"}, {"kategorie": "scherzhaft für", "text": "Tratsche, Tratschweib, Tratschziege, Klatschtante, Klatschmaul, [[Raatschn]], [[Schnoodan]], [[Tritschn]]"}]'::jsonb, 'De oide Raatschkaatl waass imma ois Easchde, wea von wem schwaunga is oda wea si von wem hod scheidn lossn!'),
